423	     8	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
424	     9	
425	    10	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
426	    11	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
427	    12	        BigDecimal subtotal = Money.ZERO;
428	    13	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
429	    14	            BigDecimal price = Seasons.isHigh(night)
430	    15	                    ? Money.round(room.nightlyRate().multiply(HIGH_SEASON))
431	    16	                    : room.nightlyRate();
432	    17	            subtotal = subtotal.add(price);
433	    18	        }
434	    19	        BigDecimal discount = plan.discount(subtotal);
435	    20	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
436	    21	    }
437	    22	}
